RaceXcpData = class("RaceXcpData")

function RaceXcpData:initialize()

    self.jcpIndexMap ={}
    self.state=1
    self.bJoin=1667529600
    self.eJoin=1667627700
    self.sceneID=29000002
    self.bTime=1668026920
    self.eTime=1668131400
    self.jcpID=1515
    self.speed1=0
    self.speed2=1
    self.speed3=3
    self.speed4=4
    self.speed5=5
