function RaceXcpData:SetDataJcupJoin(msg)
    self.join = msg.join
    self:CalculateState()
    self:RecordJoinCars()
end
---@param msg SC_RetXcup
function RaceXcpData:SetData(msg)
    self:SetTrackList(stringSplitToNumber(msg.trackids,":"))
    self.bJoin=msg.bjoin
    self.eJoin=msg.ejoin
    self.scenceids=stringSplitToNumber(msg.scenceids,":")
    self.bTime=msg.btime
    self.eTime=msg.etime
    self.Id=msg.xcupid
    self.speed1=tonumber(msg.speed1)
    self.speed2=tonumber(msg.speed2)
    self.speed3=tonumber(msg.speed3)
    self.lspeed1=tonumber(msg.lspeed1)
    self.lspeed2=tonumber(msg.lspeed2)
    self.lspeed3=tonumber(msg.lspeed3)
    self.join=msg.join
    self:CalculateState()
    self:InitIndexMap(msg.carplans)
    self.carShellList={}
    self:SetCarShell(self.carShellList,msg.carshell)
    self.lastCarShellList={}
    self:SetCarShell(self.lastCarShellList,msg.lcarshell)
    ---@type table<number, number>
    self.usedCars = {}
    for i = 1, #msg.usedcars do
        table.insert(self.usedCars,msg.usedcars[i])
    end

    if msg.firstRacer then
        self.FastPlayerData=RaceRankListPlayerData(msg.firstRacer)
    end
    if  #msg.cars >0 then
        for i = 1, 3 do
            self.jcpIndexMap[i] =0
        end
    end
    ---@type table<number, CarBuilderTextureParam>
    self.buildParams={}
    for i = 1, #msg.cars do
        local param = CarBuilderTextureParam()
        param.CarReviewData=CarReviewData()
        param.CarReviewData:SetDataByMsg(msg.cars[i])
        param.isBuildTexture = true
        param.idx=msg.cars[i].planseq
        param.positon=msg.cars[i].positon
        param.isuse=i<=#msg.usedcars
        param.isnextuse=i==(#msg.usedcars+1)
        table.insert(self.buildParams,param)
        self:SetJoinPos(msg.cars[i].positon, param.idx)
    end

end

function RaceXcpData:SetCarShell(t,str)
    local list = stringSplit(str,":")
    for i = 1, #list do
        t[i]=tonumber(list[i])
    end
end

function RaceXcpData:SetJoinPos(jcpIndex,carIndex)
    if self.jcpIndexMap[jcpIndex]~=carIndex then
        self.jcpIndexMap[jcpIndex]=carIndex
        --PlayerPrefsHelper:SetValue_JCP(self.bTime,jcpIndex,carIndex)
    end
end

function RaceXcpData:RecordJoinCars()
    local isnextuse=true
    for i = 1, #self.jcpIndexMap do
        if  self.jcpIndexMap[i]>0 then
            local param=CarBuilderTextureParam()
            param.CarReviewData=CarReviewData()
            param.CarReviewData:SetDataByCarData(CarDataManager:Get():GetCarDataByCarID(self.jcpIndexMap[i]))
            param.isBuildTexture = true
            param.idx = self.jcpIndexMap[i]
            param.positon = i
            param.isuse=false
            if isnextuse then
                param.isnextuse=true
                isnextuse=false
            end
            table.insert(self.buildParams,param)
        end
    end
end

function RaceXcpData:CalculateState()
    local curTime = CommonHelper:ConvertNowTimeDouble()
    if curTime <self.bTime then
        self.state = RaceJCPType.None
    elseif curTime< self.bJoin then
        self.state = RaceJCPType.ApplyAfter
    elseif curTime< self.eJoin then
        if self.join == 1 then
            self.state = RaceJCPType.ApplySuccess
        else
            self.state = RaceJCPType.ApplyIng
        end
    elseif curTime< self.eTime then
        self.state = RaceJCPType.RaceIng
    else
        self.state = RaceJCPType.RaceOver
    end
    --if self.state  < RaceJCPType.ApplySuccess then
    --    --self:InitIndexMap()
    --else
    --    self:ClearIndexMap()
    --end
end

function RaceXcpData:InitIndexMap(carplans)
    local indexs = stringSplit(carplans,":")
    for i = 1, 3 do
        self.jcpIndexMap[i] = tonumber(indexs[i])
    end
end

function RaceXcpData:ClearIndexMap()
    for i = 1, 3 do
        --PlayerPrefsHelper:DeleteKey_JCP(self.bTime,i)
